def _is_description_suspicious(self, description: str) -> bool:
    """
    Analyze transaction description using OpenAI GPT-4o to detect suspicious content.

    Args:
        description: Transaction description string

    Returns:
        True if description is suspicious, False otherwise (including on API errors)
    """
    if not description or not self.openai_api_key:
        return False

    try:
        response = openai.ChatCompletion.create(
            model="gpt-4o",
            messages=[
                {"role": "system", "content": "You are a fraud detection specialist. Analyze the given transaction description and return ONLY 'YES' if it seems suspicious (e.g., mentions illegal activities, scams, money laundering, prohibited goods/services, high-risk transactions) or 'NO' if it is legitimate. Do not add any other text."},
                {"role": "user", "content": f"Transaction description: {description}"}
            ],
            temperature=0.0,
            max_tokens=1,
            timeout=10
        )

        result = response.choices[0].message.content.strip().upper()
        return result == "YES"

    except Exception as e:
        logger.error(f"Failed to analyze transaction description with OpenAI: {str(e)}")
